80	/// rows, then runs FlashInfer's batched softmax + sampling — three kernel
81	/// launches, one sync, and one D2H for the whole batch.
82	///
83	/// `seed` must be fresh per decode step (one philox seed per call; rows
84	/// decorrelate through the philox subsequence). Returns one token per row, in
85	/// `rows` order.
86	///
87	/// min_p rows run as their own pass: if they shared a call, every row would
88	/// ride the min_p kernel, whose u-scaling (`u * q`) and survivor predicate
89	/// differ from the fused fast path — a min_p == 0 row could then sample a
90	/// different token than it would alone. Partitioning here (not in callers)
91	/// keeps "min_p == 0 rows take the original path" true for every caller, at
92	/// the cost of a second full pass (gather + softmax + sample, own sync) only
93	/// when a batch actually mixes.
94	pub fn gpu_sample_batch_into(
95	    ctx: &DeviceContext,
96	    logits: HiddenStatesRef<'_>,
97	    rows: &[BatchSamplingRow],
98	    seed: u64,
99	    scratch: &mut BatchSamplingScratch,
100	) -> Result<Vec<u32>> {
101	    if rows.iter().all(|r| r.min_p > 0.0) || rows.iter().all(|r| r.min_p <= 0.0) {
102	        return sample_uniform_batch_into(ctx, logits, rows, seed, scratch);
103	    }
104	    let (minp, plain): (Vec<BatchSamplingRow>, Vec<BatchSamplingRow>) =
105	        rows.iter().copied().partition(|r| r.min_p > 0.0);
106	    let plain_tokens = sample_uniform_batch_into(ctx, logits, &plain, seed, scratch)?;
107	    // Distinct philox key for the second pass: both passes restart their
108	    // subsequences at 0, so reusing `seed` would hand minp row i the same
109	    // uniform stream as plain row i and correlate their tokens.
110	    let minp_seed = seed ^ 0x9E37_79B9_7F4A_7C15;
111	    let minp_tokens = sample_uniform_batch_into(ctx, logits, &minp, minp_seed, scratch)?;
112	    let mut plain_it = plain_tokens.into_iter();
113	    let mut minp_it = minp_tokens.into_iter();
114	    Ok(rows
115	        .iter()
116	        .map(|r| {
117	            if r.min_p > 0.0 {
118	                minp_it.next().expect("minp token per minp row")
119	            } else {
120	                plain_it.next().expect("plain token per plain row")
121	            }
122	        })
123	        .collect())
124	}
125	
126	/// One homogeneous FlashInfer pass (rows are all-min_p or all-plain).
127	fn sample_uniform_batch_into(
128	    ctx: &DeviceContext,
129	    logits: HiddenStatesRef<'_>,
130	    rows: &[BatchSamplingRow],
131	    seed: u64,
132	    scratch: &mut BatchSamplingScratch,
133	) -> Result<Vec<u32>> {
134	    let n = rows.len();
135	    ensure!(n > 0, "batch sampling requires at least one row");
136	    ensure!(
137	        n <= scratch.max_rows,
138	        "batch sampling scratch too small: {n} rows > capacity {}",
139	        scratch.max_rows
140	    );
141	    ensure!(
142	        logits.hidden_dim == scratch.vocab,
143	        "batch sampling vocab mismatch: logits {} vs scratch {}",
144	        logits.hidden_dim,
145	        scratch.vocab
146	    );
147	
148	    let mut row_indices = Vec::with_capacity(n);
149	    let mut temperature = Vec::with_capacity(n);
150	    let mut top_k = Vec::with_capacity(n);
151	    let mut top_p = Vec::with_capacity(n);
152	    let mut min_p = Vec::with_capacity(n);
153	    let mut has_top_k_filter = false;
154	    let mut has_top_p_filter = false;
155	    let mut has_min_p_filter = false;
156	    for r in rows {
157	        ensure!(
158	            r.row < logits.seq_len,
159	            "batch sampling row {} out of arena range {}",
160	            r.row,
161	            logits.seq_len
162	        );
163	        ensure!(
164	            r.temperature > 0.0 && r.temperature.is_finite(),
165	            "batch sampling temperature {} must be finite and > 0 (greedy rows take the argmax path)",
166	            r.temperature
167	        );
168	        ensure!(
169	            r.top_p > 0.0 && r.top_p <= 1.0,
170	            "batch sampling top_p {} must be in (0, 1]",
171	            r.top_p
172	        );
173	        ensure!(
174	            (0.0..1.0).contains(&r.min_p) && r.min_p.is_finite(),
175	            "batch sampling min_p {} must be in [0, 1)",
176	            r.min_p
177	        );
178	        row_indices.push(i32::try_from(r.row)?);
179	        temperature.push(r.temperature);
180	        // FlashInfer reads top_k as u32; "disabled" is any k >= vocab.
181	        let vocab = i32::try_from(scratch.vocab)?;
182	        let clamped_top_k = if r.top_k > 0 && r.top_k < vocab {
183	            has_top_k_filter = true;
184	            r.top_k
185	        } else {
186	            vocab
187	        };
188	        top_k.push(clamped_top_k);
189	        if r.top_p < 1.0 {
190	            has_top_p_filter = true;
191	        }
192	        top_p.push(r.top_p);
193	        if r.min_p > 0.0 {
194	            has_min_p_filter = true;
195	        }
196	        min_p.push(r.min_p);
197	    }
198	    ctx.stream
199	        .memcpy_htod(&row_indices, &mut scratch.row_indices)?;

